// Problem An RFC 9457 problem detail, with two extension members.
type Problem struct {
	// ActionURL Where the person can go to fix the refusal — installing the board's app — for a client to offer as a button.
	ActionURL *string `json:"actionUrl,omitempty"`

	// Code The rule that refused, for a program to branch on. For a rule of the board it is that rule's own name.
	Code ProblemCode `json:"code"`

	// Detail The sentence to show a person.
	Detail string `json:"detail"`

	// Status The HTTP status, repeated in the body.
	Status int `json:"status"`

	// Title The status code's own text.
	Title string `json:"title"`

	// Type Always "about:blank": there is no page per problem, and `code` carries the identity.
	Type string `json:"type"`
}

// ProblemCode The rule that refused, for a program to branch on. For a rule of the board it is that rule's own name.
type ProblemCode string

