// ServerInterface represents all server handlers.
type ServerInterface interface {
	// GetBoard The board: title, the team roster, the Project board's structure, the people and the visitor's domains.
	// (GET /board)
	GetBoard(w http.ResponseWriter, r *http.Request, params GetBoardParams)
	// DeleteCard Hard delete, cascading to the linked review card.
	// (DELETE /cards/{uid})
	DeleteCard(w http.ResponseWriter, r *http.Request, uid UID)
	// GetCard One card in full — the body lives here, not in listings.
	// (GET /cards/{uid})
	GetCard(w http.ResponseWriter, r *http.Request, uid UID)
	// PatchCard Edit spec fields; only present fields apply, and an empty value clears.
	// (PATCH /cards/{uid})
	PatchCard(w http.ResponseWriter, r *http.Request, uid UID)
	// DeferCard Push the scheduled day N days ahead of today.
	// (POST /cards/{uid}/actions/defer)
	DeferCard(w http.ResponseWriter, r *http.Request, uid UID)
	// SetInProgress Move the card to the implicit In Progress status.
	// (POST /cards/{uid}/actions/in-progress)
	SetInProgress(w http.ResponseWriter, r *http.Request, uid UID)
	// MoveCard Reorder the card after (or before) another one.
	// (POST /cards/{uid}/actions/move)
	MoveCard(w http.ResponseWriter, r *http.Request, uid UID)
	// RemoveReviewer Take the reviewer off the card.
	// (POST /cards/{uid}/actions/remove-reviewer)
	RemoveReviewer(w http.ResponseWriter, r *http.Request, uid UID)
	// ReopenCard Undo a done mark, restoring the progress the card had when done was set.
	// (POST /cards/{uid}/actions/reopen)
	ReopenCard(w http.ResponseWriter, r *http.Request, uid UID)
	// SendToReview Send the card to a reviewer, or reassign the review that exists.
	// (POST /cards/{uid}/actions/send-to-review)
	SendToReview(w http.ResponseWriter, r *http.Request, uid UID)
	// ListLinks The URLs found in the card's description, GitHub refs resolved and listed first.
	// (GET /cards/{uid}/links)
	ListLinks(w http.ResponseWriter, r *http.Request, uid UID)
	// GetCardLog The card's activity feed — recorded events and work notes, one chronological list.
	// (GET /cards/{uid}/log)
	GetCardLog(w http.ResponseWriter, r *http.Request, uid UID)
	// ListNotes The card's work notes.
	// (GET /cards/{uid}/notes)
	ListNotes(w http.ResponseWriter, r *http.Request, uid UID)
	// AddNote Append a work note.
	// (POST /cards/{uid}/notes)
	AddNote(w http.ResponseWriter, r *http.Request, uid UID)
	// DeleteNote Delete a work note.
	// (DELETE /cards/{uid}/notes/{noteId})
	DeleteNote(w http.ResponseWriter, r *http.Request, uid UID, noteID NoteID)
	// EditNote Edit a work note.
	// (PATCH /cards/{uid}/notes/{noteId})
	EditNote(w http.ResponseWriter, r *http.Request, uid UID, noteID NoteID)
	// AddCustomer Add a customer to the board's roster, last.
	// (POST /customers)
	AddCustomer(w http.ResponseWriter, r *http.Request)
	// DeleteCustomer Delete a customer and take it off every card that names it.
	// (POST /customers/actions/delete)
	DeleteCustomer(w http.ResponseWriter, r *http.Request)
	// RenameCustomer Rename a customer; every card that names it reads the new name.
	// (POST /customers/actions/rename)
	RenameCustomer(w http.ResponseWriter, r *http.Request)
	// ReorderCustomers Apply the roster's order — the ids named first, in that order.
	// (POST /customers/actions/reorder)
	ReorderCustomers(w http.ResponseWriter, r *http.Request)
	// AddDeadline Mark a week with a project's deadline line.
	// (POST /deadlines)
	AddDeadline(w http.ResponseWriter, r *http.Request)
	// DeleteDeadline Clear a project's deadline on a week.
	// (POST /deadlines/actions/delete)
	DeleteDeadline(w http.ResponseWriter, r *http.Request)
	// MoveDeadline Drag a project's deadline to another week.
	// (POST /deadlines/actions/move)
	MoveDeadline(w http.ResponseWriter, r *http.Request)
	// GetDayLogs One day's feed for many cards at once — what a day board shows.
	// (GET /logs)
	GetDayLogs(w http.ResponseWriter, r *http.Request, params GetDayLogsParams)
	// GetOpenAPI This document, as JSON.
	// (GET /openapi.json)
	GetOpenAPI(w http.ResponseWriter, r *http.Request)
	// PatchPerson Set the points a week a PERSON gets through.
	// (PATCH /people/{login})
	PatchPerson(w http.ResponseWriter, r *http.Request, login Login)
	// SetPresence Share the caller's live card selection; an empty card clears it.
	// (POST /presence)
	SetPresence(w http.ResponseWriter, r *http.Request)
	// AddProject Declare a project — the Project board's top grouping, which owns scope columns.
	// (POST /projects)
	AddProject(w http.ResponseWriter, r *http.Request)
	// DeleteProject Delete an EMPTY project; refused while it still owns columns.
	// (POST /projects/actions/delete-project)
	DeleteProject(w http.ResponseWriter, r *http.Request)
	// RenameProject Rename a project in place; its columns and their cards follow.
	// (POST /projects/actions/rename)
	RenameProject(w http.ResponseWriter, r *http.Request)
	// ReorderProjects Apply the shared project order.
	// (POST /projects/actions/reorder-projects)
	ReorderProjects(w http.ResponseWriter, r *http.Request)
	// AddScope Declare an scope column.
	// (POST /scopes)
	AddScope(w http.ResponseWriter, r *http.Request)
	// DeleteScope Delete an EMPTY scope column; refused while cards sit under it.
	// (POST /scopes/actions/delete-scope)
	DeleteScope(w http.ResponseWriter, r *http.Request)
	// RenameScope Rename a column in place, cards and all.
	// (POST /scopes/actions/rename)
	RenameScope(w http.ResponseWriter, r *http.Request)
	// ReorderScopes Apply one project's column order.
	// (POST /scopes/actions/reorder-scopes)
	ReorderScopes(w http.ResponseWriter, r *http.Request)
	// SetScopeProject Move a column from one project to another; an empty target detaches it.
	// (POST /scopes/actions/set-project)
	SetScopeProject(w http.ResponseWriter, r *http.Request)
	// ListSprints Per-team sprint pointers.
	// (GET /sprints)
	ListSprints(w http.ResponseWriter, r *http.Request, params ListSprintsParams)
	// PatchSprint Set a team's sprint pointer directly.
	// (PATCH /sprints)
	PatchSprint(w http.ResponseWriter, r *http.Request)
	// CarryOver Advance a team's sprint to today and carry its unfinished cards.
	// (POST /sprints/actions/carry-over)
	CarryOver(w http.ResponseWriter, r *http.Request)
	// DeleteTeam Delete a team's sprint pointer; refused while cards still use the team.
	// (POST /sprints/actions/delete-team)
	DeleteTeam(w http.ResponseWriter, r *http.Request)
	// ReorderTeams Apply a shared team order.
	// (POST /sprints/actions/reorder-teams)
	ReorderTeams(w http.ResponseWriter, r *http.Request)
	// SetTeamCapacity Set the points a week a team gets through.
	// (POST /teams/actions/capacity)
	SetTeamCapacity(w http.ResponseWriter, r *http.Request)
	// RenameTeam Rename a team in place, its cards along with it.
	// (POST /teams/actions/rename)
	RenameTeam(w http.ResponseWriter, r *http.Request)
	// ListViews The boards a caller may open, each with the gestures it draws.
	// (GET /views)
	ListViews(w http.ResponseWriter, r *http.Request)
	// ListCards List the cards that board draws, in board order.
	// (GET /views/{view}/cards)
	ListCards(w http.ResponseWriter, r *http.Request, view View, params ListCardsParams)
	// CreateCard Create the card that board makes.
	// (POST /views/{view}/cards)
	CreateCard(w http.ResponseWriter, r *http.Request, view View)
	// FinishedEarlier A day board's answer for work done in the sprint before this one and marked done now.
	// (POST /views/{view}/cards/{uid}/actions/finished-earlier)
	FinishedEarlier(w http.ResponseWriter, r *http.Request, view View, uid UID, params FinishedEarlierParams)
	// OwnCard Whose is this — a team and a person on it, a team alone, or nobody.
	// (POST /views/{view}/cards/{uid}/actions/own)
	OwnCard(w http.ResponseWriter, r *http.Request, view View, uid UID, params OwnCardParams)
	// RemoveCard The board's × — hand the card back to a home it still has, or delete it by that board's rules.
	// (POST /views/{view}/cards/{uid}/actions/remove)
	RemoveCard(w http.ResponseWriter, r *http.Request, view View, uid UID, params RemoveCardParams)
	// TakeCard The Backlog's "I take this into work" — the card becomes the caller's.
	// (POST /views/{view}/cards/{uid}/actions/take)
	TakeCard(w http.ResponseWriter, r *http.Request, view View, uid UID, params TakeCardParams)
}

